import { createServer, resolveConfig } from 'vite';

const root = process.cwd().replaceAll('\\', '/');
const base = await resolveConfig({ configFile: false, logLevel: 'silent' }, 'serve');
const mine = await resolveConfig({ logLevel: 'silent' }, 'serve');
console.log('installed defaults kept:', base.server.fs.deny.every((d) => mine.server.fs.deny.includes(d)));
console.log('host:', mine.server.host, 'https:', !!mine.server.https);

// ローカルのパターン照合のみ (ファイルは読まない)
const cases = {
  '.claude/settings.json': true, '.entire/agent-guide.md': true, '.codex/x': true, '.agents/x/y.md': true,
  'AGENTS.md': true, 'CLAUDE.md': true, '.CLAUDE/x': true, '.git/config': true, '.env': true, '.env.local': true,
  'certs/a.pem': true, 'src/main.ts': false, 'index.html': false, 'src/features/handFrame.ts': false,
};
for (const [rel, want] of Object.entries(cases)) {
  const got = mine.fsDenyGlob(`${root}/${rel}`);
  console.log(got === want ? 'ok ' : 'NG ', got ? 'deny ' : 'allow', rel);
}

// 通常アセットだけネットワーク経由で確認
const server = await createServer({ logLevel: 'silent', server: { port: 5199, strictPort: true, host: '127.0.0.1' } });
await server.listen();
for (const p of ['/', '/src/main.ts']) {
  const r = await fetch(`https://127.0.0.1:5199${p}`);
  console.log(r.status, p);
}
await server.close();
process.exit(0);

